const B64 = "";
let FILES;
async function files() {
  if (FILES) return FILES;
  const bin = Uint8Array.from(atob(B64), c => c.charCodeAt(0));
  const text = await new Response(new Blob([bin]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
  FILES = JSON.parse(text);
  return FILES;
}
const ROUTES = {
  "/": "/index.html",
  "/anagram-solver": "/anagram-solver.html",
  "/scrabble-word-finder": "/scrabble-word-finder.html",
  "/words-with-friends": "/words-with-friends.html",
  "/wordle-helper": "/wordle-helper.html",
  "/jumble-solver": "/jumble-solver.html",
  "/crossword-solver": "/crossword-solver.html",
  "/words-from-letters": "/words-from-letters.html",
  "/how-it-works": "/how-it-works.html",
  "/word-lists": "/word-lists.html",
  "/2-letter-words": "/2-letter-words.html",
  "/3-letter-words": "/3-letter-words.html",
  "/4-letter-words": "/4-letter-words.html",
  "/5-letter-words": "/5-letter-words.html",
  "/6-letter-words": "/6-letter-words.html",
  "/7-letter-words": "/7-letter-words.html",
  "/8-letter-words": "/8-letter-words.html",
  "/q-without-u": "/q-without-u.html",
  "/jqxz-words": "/jqxz-words.html",
  "/bingo-stems": "/bingo-stems.html",
  "/about": "/about.html",
  "/privacy": "/privacy.html",
  "/terms": "/terms.html",
};
const MIME = {
  ".html": "text/html;charset=UTF-8",
  ".css": "text/css;charset=UTF-8",
  ".js": "text/javascript;charset=UTF-8",
  ".txt": "text/plain;charset=UTF-8",
  ".xml": "application/xml;charset=UTF-8",
  ".svg": "image/svg+xml",
  ".jpg": "image/jpeg",
};
function mime(p) {
  const i = p.lastIndexOf(".");
  return MIME[p.slice(i)] || "application/octet-stream";
}
function decode(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
async function words(request) {
  const cache = caches.default;
  const key = new Request(new URL("/words.txt", request.url).toString(), { method: "GET" });
  const hit = await cache.match(key);
  if (hit) return hit;
  const src = await fetch("https://raw.githubusercontent.com/dolph/dictionary/master/enable1.txt");
  if (!src.ok) return new Response("dictionary unavailable", { status: 502 });
  const raw = await src.text();
  const extra = "ch da di ea ee fe fy gi gu io ja ki ko ky ny ob oi ok oo ou po qi st te ug ur yu za qis zas".split(" ");
  const out = [];
  const seen = new Set();
  for (const line of raw.split(/\r?\n/)) {
    const w = line.trim().toLowerCase();
    if (w.length >= 2 && w.length <= 15 && /^[a-z]+$/.test(w) && !seen.has(w)) { seen.add(w); out.push(w); }
  }
  for (const w of extra) if (!seen.has(w)) { seen.add(w); out.push(w); }
  const resp = new Response(out.join("\n") + "\n", {
    headers: { "content-type": "text/plain;charset=UTF-8", "cache-control": "public, max-age=86400" }
  });
  await cache.put(key, resp.clone());
  return resp;
}
export default {
  async fetch(request) {
    const url = new URL(request.url);
    let p = url.pathname;
    if (p.length > 1 && p.endsWith("/")) p = p.slice(0, -1);
    if (p === "/words.txt" || p === "/words.txt.gz") return words(request);
    const map = await files();
    const resolved = ROUTES[p] || p;
    const body = map[resolved];
    if (body == null) {
      const four = map["/404.html"];
      if (four) return new Response(decode(four), { status: 404, headers: { "content-type": "text/html;charset=UTF-8" } });
      return new Response("Not found", { status: 404, headers: { "content-type": "text/plain;charset=UTF-8" } });
    }
    const bytes = decode(body);
    const headers = {
      "content-type": mime(resolved),
      "cache-control": resolved.endsWith(".html") ? "public, max-age=120" : "public, max-age=86400",
      "x-content-type-options": "nosniff",
      "referrer-policy": "strict-origin-when-cross-origin",
    };
    return new Response(bytes, { headers });
  }
};
